llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Benazeprilat, the active metabolite of the ACE inhibitor benazepril, had an absolute oral bioavailability of 27.1-28.5% when oral benazepril was compared with IV benazeprilat, supporting F >= 20% for a highly polar ACE-inhibitor-type molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Benazepril oral bioavailability was 28-37% in healthy volunteers, independently supporting that this ACE inhibitor class reaches F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Temocaprilat, another ACE inhibitor active metabolite, showed about 65% absolute oral bioavailability after oral temocapril, further supporting high oral bioavailability in this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior predicts poor permeability, direct class evidence from ACE inhibitors shows absolute oral bioavailability values of 27-65%, all above the 20% threshold. The query is therefore predicted high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule was retrieved.",
    "The physicochemical prior suggests low passive permeability, but class evidence indicates active transport or other mechanisms may overcome this; no direct transport data for the query were available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

